let raw = $('AI Agent').first().json.output || '';
raw = raw.replace(/<think>[\s\S]*?<\/think>/g, '');
const match = raw.match(/\{[\s\S]*\}/);
if (!match) throw new Error('AI did not return JSON. Got: ' + raw);
const req = JSON.parse(match[0]);

const MAX_EMAILS = 50; // safety cap, lower it if you like

const type = (req.target_type || '').toLowerCase().trim();
const value = String(req.target_value || '').toLowerCase().trim();
const get = (r, k) => String(r.json[k] ?? '').toLowerCase().trim();

let rows = $input.all();

if (type === 'person') {
  rows = rows.filter(r => get(r, 'Name').includes(value) || get(r, 'Email') === value);
} else if (type === 'list') {
  const names = value.split(',').map(s => s.trim()).filter(Boolean);
  rows = rows.filter(r => names.some(n => get(r, 'Name').includes(n) || get(r, 'Email') === n));
} else if (type === 'range') {
  const [a, b] = value.split('-').map(s => parseInt(s.trim(), 10));
  if (isNaN(a) || isNaN(b)) throw new Error('Bad range: ' + value);
  rows = rows.filter(r => Number(r.json.ID) >= a && Number(r.json.ID) <= b);
} else if (type === 'department') {
  rows = rows.filter(r => get(r, 'Role').includes(value) || get(r, 'Company') === value);
} else if (type === 'group') {
  rows = rows.filter(r => get(r, 'Category') === value || get(r, 'Status') === value);
} else if (type !== 'everyone') {
  throw new Error('Unknown target_type: ' + type);
}

// Skip fake placeholder addresses so they don't bounce
rows = rows.filter(r => !get(r, 'Email').endsWith('@example.com'));

if (rows.length === 0) throw new Error('No contacts matched ' + type + ': ' + value);
if (rows.length > MAX_EMAILS) throw new Error('Too many recipients: ' + rows.length);

return rows.map(r => ({ json: { ...r.json, subject: req.subject, body: req.body } }));
